('mw-cn-2084928', '2084928', 'Ống cắm cọ trang điểm Nếp gấp lụa thắt nơ ngọt ngào (Sweet Silk Bow Vanity Pot)', 'Ống cắm cọ Nơ Lụa Sweet Silk', 'Sweet Silk Bow Vanity Pot', 'Trang_Diem_Vanity', 139000, NULL, 'Ánh Lụa Silk Tuyển Chọn', 'Ánh Lụa Silk Tuyển Chọn', 'BÀN TRANG ĐIỂM • DÁNG NƠ COQUETTE', 'khay_dia', 'Khay Đĩa Trưng Bày', 'Nhựa Bio-PLA Silk Ánh Lụa · 90g', 'amber', 'assets/images/products/thumb_2084928.png', 'Ống cắm cọ trang điểm Nếp gấp lụa thắt nơ ngọt ngào (Sweet Silk Bow Vanity Pot)', 'T&T 3D Labs Studio', 'https://makerworld.com/en/models/2084928', 9612, 2529, 6547, 90, 18994, 100, 'PLA Silk Trắng ngọc trai / Hồng pastel', 'Cắm cọ trang điểm, son môi, bút ký bàn làm việc, decor bàn trang điểm phong cách Coquette.', 'Thiết kế nếp gấp dải lụa mềm mại kết hợp nơ phồng 3D phong cách Coquette, đứng đầu xu thế thẩm mỹ Douyin/Xiaohongshu.', '{"weight": "90g", "printTime": "5.3 giờ"}'::jsonb, '[{"id": "silk_pearl_white", "name": "Trắng Ngọc Trai Silk", "hex": "#F0ECE1"}, {"id": "silk_pastel_pink", "name": "Hồng Lụa Pastel", "hex": "#F7C6D0"}, {"id": "silk_champagne", "name": "Vàng Champagne Óng", "hex": "#EED9A7"}]'::jsonb, '[{"id": "pla_matte", "name": "PLA Matte", "label": "PLA Matte Thẩm Mỹ", "desc": "Bề mặt mờ mịn cao cấp, triệt tiêu vân in hoàn hảo", "priceModifier": 0}, {"id": "pla_silk", "name": "PLA Silk Cao Cấp", "label": "PLA Silk Óng Ánh", "desc": "Hiệu ứng phản chiếu óng ả như vải lụa tơ tằm", "priceModifier": 20000}]'::jsonb, FALSE, 'active'),
('mw-cn-2531095', '2531095', 'Bình cắm cọ trang điểm Nếp lụa thắt nơ cánh bướm lớn (Silk Bow Deluxe Caddy)', 'Bình cắm cọ Cánh Bướm Nơ Đôi', 'Silk Bow Deluxe Caddy', 'Trang_Diem_Vanity', 165000, NULL, 'Dung Tích Lớn 20 Cọ', 'Dung Tích Lớn 20 Cọ', 'BÀN TRANG ĐIỂM • CẮM CỌ CHUYÊN NGHIỆP', 'ong_cam_co', 'Ống Cắm Cọ Mỹ Phẩm', 'Chứa 15-20 cọ mỹ phẩm · Nhựa Bio-PLA', 'rose', 'assets/images/products/thumb_2531095.png', 'Bình cắm cọ trang điểm Nếp lụa thắt nơ cánh bướm lớn (Silk Bow Deluxe Caddy)', 'T&T 3D Labs Studio', 'https://makerworld.com/en/models/2531095', 8508, 2746, 6259, 135, 16337, 100, 'PLA Silk Trắng kem / Vàng Champagne', 'Đựng cọ makeup chuyên nghiệp, cắm hoa tulip giả lụa decor, khay đựng chì kẻ mày và mascara.', 'Nếp gấp lụa xếp tầng dày dặn kết hợp nơ bướm bản to ở tâm điểm, đáy bình đầm chắc chống lật.', '{"weight": "135g", "printTime": "4.5 giờ"}'::jsonb, '[{"id": "silk_pearl_white", "name": "Trắng Ngọc Trai Silk", "hex": "#F0ECE1"}, {"id": "silk_pastel_pink", "name": "Hồng Lụa Pastel", "hex": "#F7C6D0"}, {"id": "silk_champagne", "name": "Vàng Champagne Óng", "hex": "#EED9A7"}]'::jsonb, '[{"id": "pla_matte", "name": "PLA Matte", "label": "PLA Matte Thẩm Mỹ", "desc": "Bề mặt mờ mịn cao cấp, triệt tiêu vân in hoàn hảo", "priceModifier": 0}, {"id": "pla_silk", "name": "PLA Silk Cao Cấp", "label": "PLA Silk Óng Ánh", "desc": "Hiệu ứng phản chiếu óng ả như vải lụa tơ tằm", "priceModifier": 20000}]'::jsonb, FALSE, 'active'),
('mw-cn-1646129', '1646129', 'Khay đĩa lụa mềm thắt nơ đựng trang sức & chìa khóa (Coquette Silk Ribbon Vanity Tray)', 'Khay trang sức Nơ Lụa Sweet Silk', 'Coquette Silk Ribbon Vanity Tray', 'Trang_Diem_Vanity', 119000, NULL, '✦ Lựa Chọn Tiêu Biểu', '✦ Lựa Chọn Tiêu Biểu', 'GÓC RA VÀO • TRANG SỨC & CHÌA KHÓA', 'khay_dia', 'Khay Đĩa Trưng Bày', 'Đĩa lụa mềm vát cong · Trưng bày đồng hồ', 'terracotta', 'assets/images/products/thumb_1646129.png', 'Khay đĩa lụa mềm thắt nơ đựng trang sức & chìa khóa (Coquette Silk Ribbon Vanity Tray)', 'TheHexArtist', 'https://makerworld.com/en/models/1646129', 12437, 3944, 8973, 87, 16101, 100, 'PLA Silk Trắng ngọc / Hồng đào', 'Đựng nhẫn, vòng tay, đồng hồ, chìa khóa nhà tại lối ra vào hoặc bàn trang điểm.', 'Khay dáng đĩa uốn lượn như dải lụa mềm đặt trên bàn trang điểm, góc khay đính nơ bướm tinh xảo.', '{"weight": "87g", "printTime": "4.5 giờ"}'::jsonb, '[{"id": "silk_pearl_white", "name": "Trắng Ngọc Trai Silk", "hex": "#F0ECE1"}, {"id": "silk_pastel_pink", "name": "Hồng Lụa Pastel", "hex": "#F7C6D0"}, {"id": "silk_champagne", "name": "Vàng Champagne Óng", "hex": "#EED9A7"}]'::jsonb, '[{"id": "pla_matte", "name": "PLA Matte", "label": "PLA Matte Thẩm Mỹ", "desc": "Bề mặt mờ mịn cao cấp, triệt tiêu vân in hoàn hảo", "priceModifier": 0}, {"id": "pla_silk", "name": "PLA Silk Cao Cấp", "label": "PLA Silk Óng Ánh", "desc": "Hiệu ứng phản chiếu óng ả như vải lụa tơ tằm", "priceModifier": 20000}]'::jsonb, TRUE, 'active'),
('mw-cn-2053572', '2053572', 'Hộp trang sức nắp đậy nếp lụa quả đào thắt nơ (Silk Pleated Peach Jewelry Box)', 'Hộp trang sức Quả Đào Nếp Lụa', 'Silk Pleated Peach Jewelry Box', 'Trang_Diem_Vanity', 159000, NULL, 'Nắp Đậy Kín Chống Bụi', 'Nắp Đậy Kín Chống Bụi', 'BÀN PHẤN • BẢO QUẢN KHUYÊN TAI', 'hop_trang_suc', 'Hộp Đựng Trang Sức', 'Ngăn chứa tròn sâu lòng · Nắp tháo rời', 'rose', 'assets/images/products/thumb_2053572.png', 'Hộp trang sức nắp đậy nếp lụa quả đào thắt nơ (Silk Pleated Peach Jewelry Box)', 'T&T 3D Labs Studio', 'https://makerworld.com/en/models/2053572', 3182, 1050, 2262, 142, 12280, 100, 'PLA Silk Hồng phấn / Trắng ngọc trai', 'Cất giữ bông tai, dây chuyền quý giá, kẹo cưới cao cấp, quà tặng lễ tình nhân.', 'Thân hộp tạo khối quả đào nếp gấp múi lụa xoắn ốc, nắp khít gắn nam châm giấu kín, đỉnh nắp thắt nơ ribbon.', '{"weight": "142g", "printTime": "3.4 giờ"}'::jsonb, '[{"id": "silk_pearl_white", "name": "Trắng Ngọc Trai Silk", "hex": "#F0ECE1"}, {"id": "silk_pastel_pink", "name": "Hồng Lụa Pastel", "hex": "#F7C6D0"}, {"id": "silk_champagne", "name": "Vàng Champagne Óng", "hex": "#EED9A7"}]'::jsonb, '[{"id": "pla_matte", "name": "PLA Matte", "label": "PLA Matte Thẩm Mỹ", "desc": "Bề mặt mờ mịn cao cấp, triệt tiêu vân in hoàn hảo", "priceModifier": 0}, {"id": "pla_silk", "name": "PLA Silk Cao Cấp", "label": "PLA Silk Óng Ánh", "desc": "Hiệu ứng phản chiếu óng ả như vải lụa tơ tằm", "priceModifier": 20000}]'::jsonb, FALSE, 'active'),
