('mw-cn-2332220', '2332220', 'Hộp vỏ sò lụa thắt nơ ngọc trai đựng nhẫn & dây chuyền (Silk Seashell Bow Jewelry Box)', 'Hộp nhẫn Vỏ Sò Thắt Nơ', 'Silk Seashell Bow Jewelry Box', 'Trang_Diem_Vanity', 169000, NULL, 'Khóa Bản Lề Liền Khối', 'Khóa Bản Lề Liền Khối', 'QUÀ TẶNG • CẦU HÔN & KỶ NIỆM', 'hop_trang_suc', 'Hộp Đựng Trang Sức', 'Khớp mở góc 90° · Lót nhung đáy khay', 'terracotta', 'assets/images/products/thumb_2332220.png', 'Hộp vỏ sò lụa thắt nơ ngọc trai đựng nhẫn & dây chuyền (Silk Seashell Bow Jewelry Box)', 'CBT3000', 'https://makerworld.com/en/models/2332220', 2232, 840, 1596, 140, 20196, 100, 'PLA Silk Trắng ánh trai / Hồng vỏ sò', 'Đựng trang sức quý, nhẫn đính hôn, ngọc trai, trang trí bàn phấn phong cách nàng tiên cá Mermaidcore.', 'Sự kết hợp giữa vỏ sò biển khép mở và bề mặt xếp nếp lụa đính nơ, phong cách tiểu thư cổ điển quý phái.', '{"weight": "140g", "printTime": "5.6 giờ"}'::jsonb, '[{"id": "silk_pearl_white", "name": "Trắng Ngọc Trai Silk", "hex": "#F0ECE1"}, {"id": "silk_pastel_pink", "name": "Hồng Lụa Pastel", "hex": "#F7C6D0"}, {"id": "silk_champagne", "name": "Vàng Champagne Óng", "hex": "#EED9A7"}]'::jsonb, '[{"id": "pla_matte", "name": "PLA Matte", "label": "PLA Matte Thẩm Mỹ", "desc": "Bề mặt mờ mịn cao cấp, triệt tiêu vân in hoàn hảo", "priceModifier": 0}, {"id": "pla_silk", "name": "PLA Silk Cao Cấp", "label": "PLA Silk Óng Ánh", "desc": "Hiệu ứng phản chiếu óng ả như vải lụa tơ tằm", "priceModifier": 20000}]'::jsonb, FALSE, 'active'),
